"use client";

import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface Text01Props {
  text?: string;
  className?: string;
  containerClassName?: string;
}

export default function Text_01({
  text = "Build with intention.",
  className,
  containerClassName,
}: Text01Props) {
  return (
    <motion.div
      initial="initial"
      whileHover="hover"
      className={cn(
        "group relative inline-block overflow-hidden",
        containerClassName,
      )}
    >
      <motion.span
        className={cn(
          "relative block text-4xl font-semibold tracking-[-0.04em] text-zinc-200",
          className,
        )}
        variants={{
          initial: { y: 0 },
          hover: { y: -2 },
        }}
        transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
      >
        {text}

        <motion.span
          className="absolute inset-x-0 bottom-0 h-px origin-left bg-gradient-to-r from-transparent via-violet-400 to-transparent"
          variants={{
            initial: { scaleX: 0, opacity: 0 },
            hover: { scaleX: 1, opacity: 1 },
          }}
          transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
        />
      </motion.span>
    </motion.div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface TextSplitProps {
  text?: string;
  className?: string;
  containerClassName?: string;
  splitSpacing?: number;
}

export default function Text_02({
  text = "Payout fees",
  className = "",
  containerClassName = "",
  splitSpacing = 3,
}: TextSplitProps) {
  return (
    <motion.div
      initial="default"
      whileHover="hover"
      className={cn(
        "relative inline-block w-full text-center",
        containerClassName,
      )}
    >
      <motion.div
        className={cn(
          "absolute inset-x-0 text-4xl font-semibold tracking-[-0.04em]",
          className,
        )}
        variants={{
          default: {
            clipPath: "inset(0 0 50% 0)",
            y: -splitSpacing / 2,
          },
          hover: {
            clipPath: "inset(0 0 100% 0)",
            y: -splitSpacing,
          },
        }}
        transition={{
          duration: 0.25,
          ease: [0.22, 1, 0.36, 1],
        }}
      >
        {text}
      </motion.div>

      <motion.div
        className={cn(
          "absolute inset-x-0 text-4xl font-semibold tracking-[-0.04em]",
          className,
        )}
        variants={{
          default: {
            clipPath: "inset(50% 0 0 0)",
            y: splitSpacing / 2,
          },
          hover: {
            clipPath: "inset(100% 0 0 0)",
            y: splitSpacing,
          },
        }}
        transition={{
          duration: 0.25,
          ease: [0.22, 1, 0.36, 1],
        }}
      >
        {text}
      </motion.div>

      <motion.div
        className={cn(
          "relative text-4xl font-semibold tracking-[-0.04em] text-zinc-200",
          className,
        )}
        variants={{
          default: {
            opacity: 0,
          },
          hover: {
            opacity: 1,
          },
        }}
        transition={{
          duration: 0.2,
          delay: 0.08,
        }}
      >
        {text}
      </motion.div>
    </motion.div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface Text03Props {
  text?: string;
  className?: string;
  containerClassName?: string;
}

export default function Text_03({
  text = "Move faster.",
  className,
  containerClassName,
}: Text03Props) {
  const characters = [...text];

  return (
    <motion.div
      initial="initial"
      whileHover="hover"
      className={cn(
        "inline-flex flex-wrap",
        containerClassName,
      )}
      aria-label={text}
    >
      {characters.map((character, index) => (
        <motion.span
          key={`${character}-${index}`}
          className={cn(
            "inline-block whitespace-pre text-4xl font-semibold tracking-[-0.04em] text-zinc-200",
            className,
          )}
          variants={{
            initial: {
              y: 0,
              opacity: 1,
            },
            hover: {
              y: character === " " ? 0 : -5,
              opacity: 1,
            },
          }}
          transition={{
            duration: 0.25,
            delay: index * 0.018,
            ease: [0.22, 1, 0.36, 1],
          }}
        >
          {character}
        </motion.span>
      ))}
    </motion.div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface Text04Props {
  text?: string;
  className?: string;
  containerClassName?: string;
}

export default function Text_04({
  text = "System online.",
  className,
  containerClassName,
}: Text04Props) {
  return (
    <motion.div
      initial="initial"
      whileHover="hover"
      className={cn(
        "relative inline-block",
        containerClassName,
      )}
    >
      <span
        className={cn(
          "relative z-10 text-4xl font-semibold tracking-[-0.04em] text-zinc-200",
          className,
        )}
      >
        {text}
      </span>

      <motion.span
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute left-0 top-0 text-4xl font-semibold tracking-[-0.04em] text-violet-400/70",
          className,
        )}
        variants={{
          initial: {
            x: 0,
            opacity: 0,
          },
          hover: {
            x: -2,
            opacity: 0.7,
          },
        }}
        transition={{
          duration: 0.12,
          ease: "easeOut",
        }}
      >
        {text}
      </motion.span>

      <motion.span
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute left-0 top-0 text-4xl font-semibold tracking-[-0.04em] text-indigo-400/50",
          className,
        )}
        variants={{
          initial: {
            x: 0,
            opacity: 0,
          },
          hover: {
            x: 2,
            opacity: 0.5,
          },
        }}
        transition={{
          duration: 0.1,
          delay: 0.03,
          ease: "easeOut",
        }}
      >
        {text}
      </motion.span>

      <motion.span
        className="absolute -bottom-2 left-0 h-px bg-violet-400"
        variants={{
          initial: {
            width: 0,
            opacity: 0,
          },
          hover: {
            width: "28%",
            opacity: 1,
          },
        }}
        transition={{
          duration: 0.25,
          ease: [0.22, 1, 0.36, 1],
        }}
      />
    </motion.div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { motion } from "motion/react";

interface Text05Props {
  text?: string;
  className?: string;
  containerClassName?: string;
}

export default function Text_05({
  text = "Design systems that scale.",
  className,
  containerClassName,
}: Text05Props) {
  return (
    <motion.div
      initial="initial"
      whileHover="hover"
      className={cn(
        "group relative inline-block cursor-default",
        containerClassName,
      )}
    >
      <motion.span
        className={cn(
          "relative block text-4xl font-semibold tracking-[-0.04em] text-zinc-200",
          className,
        )}
        variants={{
          initial: {
            color: "rgb(228 228 231)",
          },
          hover: {
            color: "rgb(255 255 255)",
          },
        }}
        transition={{ duration: 0.25 }}
      >
        {text}

        <motion.span
          className="absolute -bottom-1 left-0 h-px bg-violet-400"
          variants={{
            initial: {
              width: "18%",
              opacity: 0.45,
            },
            hover: {
              width: "100%",
              opacity: 1,
            },
          }}
          transition={{
            duration: 0.45,
            ease: [0.22, 1, 0.36, 1],
          }}
        />

        <motion.span
          className="absolute -bottom-1 left-0 h-px bg-white"
          variants={{
            initial: {
              x: "-100%",
              width: "25%",
              opacity: 0,
            },
            hover: {
              x: "400%",
              width: "25%",
              opacity: 0.8,
            },
          }}
          transition={{
            duration: 0.65,
            ease: "easeInOut",
          }}
        />
      </motion.span>
    </motion.div>
  );
}
